from http_client import Response, request_with_retry


class HttpClientTest(unittest.TestCase):
    def test_retries_429_with_retry_after_delta(self):
        calls = []
        slept = []

        def client(url):
            calls.append(url)
            if len(calls) == 1:
                return Response(429, headers={"Retry-After": "2"})
            return Response(200, "ok")

        response = request_with_retry(
            "https://example.invalid/data",
            client=client,
            max_attempts=3,
            sleep=slept.append,
        )

        self.assertEqual(response.status, 200)
        self.assertEqual(response.body, "ok")
        self.assertEqual(calls, ["https://example.invalid/data", "https://example.invalid/data"])
        self.assertEqual(slept, [2])


if __name__ == "__main__":
    unittest.main()

from dataclasses import dataclass, field
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from time import sleep as default_sleep


@dataclass
class Response:
    status: int
    body: str = ""
    headers: dict[str, str] = field(default_factory=dict)


def request_with_retry(url, client, max_attempts=3, sleep=None, now=None):
    sleep = default_sleep if sleep is None else sleep
    now = (lambda: datetime.now(timezone.utc)) if now is None else now
    attempts = max(1, max_attempts)

    for attempt in range(attempts):
        response = client(url)
        if response.status not in {429, 500, 502, 503, 504}:
            return response
        if attempt == attempts - 1:
            return response

        sleep(_retry_after_delay(response.headers, now))

    return response


def _retry_after_delay(headers, now):
    retry_after = _header_value(headers, "Retry-After")
    if retry_after is None:
        return 0

    try:
        return max(0, int(retry_after))
    except ValueError:
        pass

    try:
        retry_at = parsedate_to_datetime(retry_after)
    except (TypeError, ValueError, IndexError, OverflowError):
        return 0

    if retry_at.tzinfo is None:
        retry_at = retry_at.replace(tzinfo=timezone.utc)

    current = now()
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)

    return max(0, int((retry_at - current).total_seconds()))


def _header_value(headers, name):
    for key, value in headers.items():
        if key.lower() == name.lower():
            return value
    return None
